		data: b.data.with_cleared('prev').with_added('prev', [id.str()])
	}
}

// set_prev sets `prev` to `node`.
pub fn (b NodeUpdate) set_prev(node NodeNode) NodeUpdate {
	return NodeUpdate{
		...b
		data: b.data.with_cleared('prev').with_added('prev', [node.node.id.str()])
	}
}

// clear_prev removes the `prev`.
pub fn (b NodeUpdate) clear_prev() NodeUpdate {
	return NodeUpdate{
		...b
		data: b.data.with_cleared('prev')
	}
}

// exec updates the rows and their edges, in one transaction, and returns how
// many there were.
pub fn (b NodeUpdate) exec() !int {
	return b.graph.client.update(b.data)
}

// NodeDeleteOne builds the delete of one `nodes` row. Start one with
// `Graph.nodes().delete_one(node)` or `delete_one_id(id)`.
pub struct NodeDeleteOne {
	graph Graph
pub:
	data vgraph.MutationData
}

// delete_one starts the delete of the row of `node`.
pub fn (q NodeQuery) delete_one(node NodeNode) NodeDeleteOne {
	return q.delete_one_id(node.node.id)
}

// delete_one_id starts the delete of the row with the key `id`.
pub fn (q NodeQuery) delete_one_id(id int) NodeDeleteOne {
	return NodeDeleteOne{
		graph: q.graph
		data:  vgraph.MutationData{
			op:      .delete_one
			table:   'nodes'
			row_key: id.str()
		}
	}
}

// exec deletes the row, with its join table rows, in one transaction, or
// returns a `NotFoundError`.
pub fn (b NodeDeleteOne) exec() ! {
	if !b.graph.client.delete_one(b.data)! {
		return NotFoundError{
			table: 'nodes'
		}
	}
}

// NodeDelete builds the delete of the `nodes` rows that match its conditions.
// Start one with `Graph.nodes().delete()`.
pub struct NodeDelete {
	graph Graph
pub:
	data vgraph.MutationData
}

// delete starts the delete of the rows that match the query's conditions; its
// order, limit and offset don't apply.
pub fn (q NodeQuery) delete() NodeDelete {
	return NodeDelete{
		graph: q.graph
		data:  vgraph.MutationData{
			op:    .delete
			table: 'nodes'
			conds: q.query.conds.clone()
		}
	}
}

// where keeps the rows that match every one of `conds`.
pub fn (b NodeDelete) where(conds ...load.Cond) NodeDelete {
	return NodeDelete{
		...b
		data: b.data.with_conds(conds)
	}
}

